<?php require_once __DIR__.'/../includes/studio.php';
$stats = row("SELECT (SELECT COUNT(*) FROM customers) customers,(SELECT COUNT(*) FROM products) products,(SELECT COUNT(*) FROM orders) orders,(SELECT COUNT(*) FROM orders WHERE order_status='pending') pending,(SELECT COALESCE(SUM(amount),0) FROM payments WHERE payment_status='paid') sales");
studio_head('Studio overview', 'dashboard', 'A live reading of the store, its wardrobe, and its orders.');?>
<div class="stats"><article class="sales-stat"><p>Verified sales</p><strong><?=money($stats['sales'])?></strong><small>Paid payments only</small></article><?php foreach (['customers' => 'Customers','products' => 'Product SKUs','orders' => 'Total orders','pending' => 'Pending orders'] as $k => $name):?><article><p><?=$name?></p><strong><?=$stats[$k]?></strong></article><?php endforeach;?></div><div class="admin-section-title"><h2>Recent orders</h2><a class="text-link" href="<?=u('admin/orders.php')?>">All orders ↗</a></div><?php orders_table(rows(ORDER_TOTALS.' ORDER BY o.order_id DESC LIMIT 8'));?><div class="admin-section-title"><h2>Inventory snapshot</h2><a class="text-link" href="<?=u('admin/products.php')?>">Manage pieces ↗</a></div><div class="inventory-snapshot"><?php foreach (rows(PRODS.' ORDER BY p.stock_qty,p.product_id LIMIT 5') as $p):?><a href="<?=u('admin/product-edit.php?id='.$p['product_id'])?>"><img src="<?=h(image_for($p))?>" alt=""><div><b><?=h($p['sku'])?></b><small><?=$p['stock_qty']?> in stock · <?=money($p['price'])?></small></div></a><?php endforeach;?></div><?php studio_foot();?>
